<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>M.I.S.T. UI Redesign Analysis</title>
    <style>
        :root {
            --bg-dark: #0f1115;
            --bg-panel: #161920;
            --bg-sidebar: #1a1d26;
            --text-main: #e2e8f0;
            --text-muted: #64748b;
            --accent-purple: #8b5cf6;
            --accent-purple-dim: rgba(139, 92, 246, 0.15);
            --border-color: #2d3342;
            --glass-bg: rgba(255, 255, 255, 0.03);
            --glass-border: rgba(255, 255, 255, 0.08);
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-dark);
            color: var(--text-main);
            font-family: var(--font-sans);
            line-height: 1.5;
            padding: 40px 20px;
            display: flex;
            justify-content: center;
        }

        .container {
            max-width: 1200px;
            width: 100%;
            display: grid;
            grid-template-columns: 280px 1fr;
            gap: 24px;
        }

        /* Sidebar / Evaluation Panel */
        aside {
            position: sticky;
            top: 24px;
            height: fit-content;
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .eval-card {
            background: var(--bg-panel);
            border: 1px solid var(--border-color);
            border-radius: 12px;
            padding: 20px;
        }

        .eval-header {
            font-size: 14px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--text-muted);
            margin-bottom: 12px;
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 8px;
        }

        .eval-item {
            margin-bottom: 16px;
        }

        .eval-item:last-child { margin-bottom: 0; }

        .question {
            font-weight: 600;
            font-size: 15px;
            margin-bottom: 4px;
            display: block;
        }

        .answer {
            font-size: 13px;
            color: var(--text-muted);
            padding-left: 10px;
            border-left: 2px solid var(--accent-purple);
        }

        .status-badge {
            display: inline-block;
            padding: 2px 8px;
            border-radius: 4px;
            font-size: 11px;
            font-weight: bold;
            text-transform: uppercase;
        }
        .status-good { background: rgba(34, 197, 94, 0.15); color: #22c55e; }
        .status-warn { background: rgba(234, 179, 8, 0.15); color: #eab308; }

        /* Main Content Area - The UI Mockup */
        main {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        /* Top Navbar */
        header.top-nav {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 12px 20px;
            background: var(--bg-panel);
            border: 1px solid var(--border-color);
            border-radius: 12px;
        }

        .brand {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .logo-circle {
            width: 32px;
            height: 32px;
            background: radial-gradient(circle at 30% 30%, #4a5568, #1a202c);
            border-radius: 50%;
            border: 1px solid #4a5568;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            font-weight: bold;
            color: #a0aec0;
        }

        .brand-text h1 {
            font-size: 14px;
            font-weight: 700;
            letter-spacing: 0.1em;
            line-height: 1.2;
        }
        .brand-text span {
            font-size: 10px;
            color: var(--text-muted);
            letter-spacing: 0.05em;
        }

        /* Segmented Glass Control (The Redesign Feature) */
        .nav-controls {
            display: flex;
            align-items: center;
            background: var(--glass-bg);
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
            border: 1px solid var(--glass-border);
            padding: 4px;
            border-radius: 999px; /* Pill shape */
            gap: 4px;
        }

        .nav-pill {
            padding: 6px 16px;
            border-radius: 999px;
            font-size: 12px;
            cursor: pointer;
            transition: all 0.2s ease;
            color: var(--text-muted);
            display: flex;
            align-items: center;
            gap: 6px;
            border: none;
            background: transparent;
        }

        .nav-pill:hover {
            color: var(--text-main);
            background: rgba(255,255,255,0.05);
        }

        .nav-pill.active {
            background: rgba(139, 92, 246, 0.2); /* Subtle tint */
            color: white;
            font-weight: 600;
            box-shadow: 0 0 10px rgba(139, 92, 246, 0.1);
        }

        .nav-icon-placeholder {
            width: 14px;
            height: 14px;
            opacity: 0.7;
        }

        .header-actions {
            display: flex;
            align-items: center;
            gap: 16px;
            font-size: 12px;
            color: var(--text-muted);
        }

        /* Main App Layout */
        .app-grid {
            display: grid;
            grid-template-columns: 240px 1fr;
            gap: 20px;
            min-height: 600px;
        }

        /* Sidebar Threads */
        .threads-sidebar {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .sidebar-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 11px;
            font-weight: 700;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            padding-left: 4px;
        }

        /* Full Width Primary Button (The Redesign Feature) */
        .btn-new-thread {
            width: 100%;
            padding: 10px;
            background: linear-gradient(135deg, var(--accent-purple), #6d28d9);
            color: white;
            border: none;
            border-radius: 8px;
            font-weight: 600;
            font-size: 13px;
            cursor: pointer;
            text-align: left;
            display: flex;
            justify-content: space-between;
            align-items: center;
            box-shadow: 0 4px 12px rgba(139, 92, 246, 0.25);
            transition: transform 0.1s;
        }
        .btn-new-thread:active { transform: scale(0.98); }

        /* Active Thread Item (The Redesign Feature) */
        .thread-item {
            padding: 12px;
            border-radius: 8px;
            cursor: pointer;
            position: relative;
            transition: background 0.2s;
            border: 1px solid transparent;
        }

        /* Inactive state */
        .thread-item:not(.active) {
            background: rgba(255,255,255,0.02);
        }
        .thread-item:not(.active):hover {
            background: rgba(255,255,255,0.05);
        }

        /* Active State Styling */
        .thread-item.active {
            background: var(--accent-purple-dim); /* Tinted Background */
            border-color: rgba(139, 92, 246, 0.3);
        }

        /* Purple Left Accent */
        .thread-item.active::before {
            content: '';
            position: absolute;
            left: 0;
            top: 4px;
            bottom: 4px;
            width: 3px;
            background: var(--accent-purple);
            border-radius: 0 4px 4px 0;
        }

        .thread-title {
            font-size: 13px;
            font-weight: 500;
            margin-bottom: 4px;
            color: var(--text-main);
        }

        .thread-meta {
            font-size: 11px;
            color: var(--text-muted);
        }

        /* Chat Area */
        .chat-area {
            background: var(--bg-panel);
            border: 1px solid var(--border-color);
            border-radius: 12px;
            display: flex;
            flex-direction: column;
            overflow: hidden;
            position: relative;
        }

        .chat-header-bar {
            padding: 16px 24px;
            border-bottom: 1px solid var(--border-color);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .chat-title-large {
            font-weight: 600;
            font-size: 14px;
        }

        .chat-controls {
            display: flex;
            gap: 8px;
        }

        .mini-select {
            background: rgba(0,0,0,0.2);
            border: 1px solid var(--border-color);
            color: var(--text-muted);
            padding: 4px 8px;
            border-radius: 6px;
            font-size: 11px;
        }

        .chat-body {
            flex: 1;
            padding: 40px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-align: center;
