        .avatar-core {
            width: 48px;
            height: 48px;
            background: radial-gradient(circle at 30% 30%, #4a5568, #1a202c);
            border-radius: 50%;
            margin-bottom: 16px;
            box-shadow: 0 0 20px rgba(0,0,0,0.5);
