        .welcome-text h2 {
            font-size: 18px;
            margin-bottom: 8px;
            font-weight: 600;
        }
        .welcome-text p {
            font-size: 12px;
            color: var(--text-muted);
            margin-bottom: 32px;
            letter-spacing: 0.05em;
        }

        .suggestion-chips {
            display: flex;
            flex-direction: column;
            gap: 10px;
            max-width: 480px;
            width: 100%;
        }

        .chip {
            background: rgba(255,255,255,0.04);
            border: 1px solid var(--border-color);
            padding: 10px 16px;
            border-radius: 99px;
            font-size: 12px;
            color: var(--text-muted);
            cursor: pointer;
            transition: all 0.2s;
            text-align: center;
        }
        .chip:hover {
            background: rgba(255,255,255,0.08);
            color: var(--text-main);
            border-color: rgba(255,255,255,0.2);
        }

        .input-area {
            padding: 20px 24px;
            border-top: 1px solid var(--border-color);
            background: rgba(0,0,0,0.2);
        }

        .input-wrapper {
            background: rgba(0,0,0,0.3);
            border: 1px solid var(--border-color);
            border-radius: 12px;
            padding: 12px 16px;
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .input-wrapper input {
            background: transparent;
            border: none;
            color: white;
            flex: 1;
            outline: none;
            font-size: 14px;
        }
        .input-wrapper input::placeholder { color: #4a5568; }

        .icon-btn {
            background: none;
            border: none;
            color: var(--text-muted);
            cursor: pointer;
            padding: 4px;
        }
        .icon-btn.send { color: var(--accent-purple); }

        .status-footer {
            margin-top: 12px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 10px;
            color: var(--text-muted);
            font-family: monospace;
        }

        .listening-badge {
            color: #10b981;
            border: 1px solid #10b981;
            padding: 2px 6px;
            border-radius: 4px;
            text-transform: uppercase;
        }

        /* Responsive */
        @media (max-width: 900px) {
            .container { grid-template-columns: 1fr; }
            .app-grid { grid-template-columns: 1fr; }
            .threads-sidebar { display: none; } /* Hide sidebar on mobile for this demo focus */
            .top-nav { flex-wrap: wrap; gap: 10px; }
            .nav-controls { order: 3; width: 100%; justify-content: center; }
        }
    </style>
</head>
